tariff "t"
let s = { kind: Delivery, appointment: true }
let label = match s {
  { kind: Delivery, appointment: true } => "appointed delivery"
  _ => "other"
}
note "{label}"

tariff "t"
let s = { kind: Delivery, appointment: false }
let label = match s {
  { kind: Delivery, appointment: true } => "appointed delivery"
  _ => "other"
}
note "{label}"

tariff "t"
let n = 2
match n {
  1 => {
    note "one"
  }
  2 => {
    note "two"
    note "still two"
  }
  _ => {
    note "many"
  }
}

tariff "t"
let n = 4
let doubled = match n {
  x => x * 2
}
note "{doubled}"

tariff "t"
let n = 9
let label = match n {
  1 => "one"
}

tariff "t"
let d = @2026-07-04
let season = match d {
  @2026-06-01..@2026-09-01 => "summer"
  _ => "other"
}
note "{season}"
